"""Rebuild only the module catalog and viewer HTML; never edit the study note."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent;M=R/'Modules';catalog=json.loads((M/'catalog.json').read_text())
def esc(v):return html.escape(str(v),quote=True)
def shell(title,body,extra=''):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · CS Exit Ethiopia</title><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/modules.css"></head><body>'+body+extra+'</body></html>'
def nav():return '<nav class="modules-nav" aria-label="Study hub"><a href="../index.html">Home</a><a href="../Complete_CS_Exit_Study_Guide.html">Study guide</a><a href="../Questions/Interactive_Study_Guides/index.html">Questions</a><a href="../Outlines/index.html">Outlines</a><a href="index.html">All modules</a></nav>'
body='<header class="container modules-intro">'+nav()+'<p class="eyebrow">Original course materials</p><h1>Modules for all 16 courses</h1><p>Read the original module PDFs here, or download them for offline study. Database Fundamentals and Advanced Database share one PDF; Networking and System Administration share another. Each course opens at its relevant starting page.</p><input type="search" id="module-search" class="module-search" placeholder="Find a course…" aria-label="Search module courses"><p class="modules-count" id="module-count" aria-live="polite">16 courses · 14 original PDFs</p></header><main class="container"><div class="modules-grid">'
for c in catalog['courses']:
 body+='<article class="module-card" data-course="'+esc(c['course'].lower())+'"><h2>'+esc(c['course'])+'</h2><p class="module-meta">'+str(c['pages'])+' pages · '+format(c['bytes']/1048576,'.1f')+' MB</p>'
 if c.get('shared_note'):body+='<p class="shared-module">'+esc(c['shared_note'])+'</p>'
 body+='<div class="module-actions"><a class="module-button" href="'+esc(c['slug'])+'.html">View module</a><a class="module-button secondary" href="'+esc(c['file'])+'" download="'+esc(c['slug'])+'_Module.pdf">Download PDF</a></div></article>'
 config={k:c[k]for k in ['slug','course','file','pages','start_page']}
 viewer='<header class="container module-view-header">'+nav()+'<h1>'+esc(c['course'])+'</h1><p>'+esc(c.get('shared_note')or'Original course module. Use the page controls to read, or download a copy for offline study.')+'</p><div class="module-actions"><a class="module-button" id="open-pdf" href="'+esc(c['file'])+'#page='+str(c['start_page'])+'" target="_blank" rel="noopener">Open PDF</a><a class="module-button secondary" id="download-pdf" href="'+esc(c['file'])+'" download="'+esc(c['slug'])+'_Module.pdf">Download PDF</a><a class="module-button secondary" href="../Complete_CS_Exit_Study_Guide.html#course-'+esc(c['slug'])+'">Read the study guide</a></div></header><main class="container module-view-main"><div class="pdf-controls" aria-label="PDF page controls"><button id="previous-page" type="button" disabled>← Previous</button><label class="pdf-page-label">Page <input type="number" id="page-number" min="1" max="'+str(c['pages'])+'" value="'+str(c['start_page'])+'" disabled> of <span id="page-total">'+str(c['pages'])+'</span></label><button type="button" id="next-page" disabled>Next →</button><label class="pdf-zoom-label">Zoom <select id="pdf-zoom" disabled><option value="1">Fit width</option><option value="1.25">125%</option><option value="1.5">150%</option><option value="2">200%</option></select></label></div><div id="pdf-stage" class="pdf-stage" aria-busy="true"><div class="canvas-sheet"><canvas id="pdf-canvas" class="pdf-canvas" role="img" aria-label="Loading module PDF"></canvas></div></div><p id="viewer-status" class="viewer-status" role="status" aria-live="polite">Loading module PDF…</p><p class="pdf-alternative">The original PDF is unchanged. For text selection, printing or your browser’s PDF search, choose “Open PDF”. “Download PDF” saves the complete document, including both courses when a PDF is shared.</p><noscript><p>Open or download the PDF using the links above.</p></noscript></main>'
 extra='<script id="module-config" type="application/json">'+json.dumps(config,ensure_ascii=False).replace('</',r'<\/')+'</script><script type="module" src="../assets/module-viewer.js"></script>'
 (M/(c['slug']+'.html')).write_text(shell(c['course']+' module',viewer,extra))
body+='</div><p class="modules-empty" id="modules-empty" hidden>No matching course. Try another search.</p></main><footer class="container"><p class="pdf-alternative">The complete study guide remains unchanged. These original PDFs are available as additional references.</p></footer><script>document.getElementById("module-search").oninput=function(){const q=this.value.trim().toLowerCase();let count=0;document.querySelectorAll(".module-card").forEach(c=>{c.hidden=!c.dataset.course.includes(q);if(!c.hidden)count++});document.getElementById("module-count").textContent=count+" / 16 courses shown";document.getElementById("modules-empty").hidden=count!==0};</script>'
(M/'index.html').write_text(shell('Course modules',body));print('Generated16courseviewers+modulecatalog; PDFfilesunchanged.')
